"use client"

import { SidebarNav } from "./sidebar-nav"
import type { ReactNode } from "react"
import { Button } from "./ui/button"
import { LogOut, User, Shield } from "lucide-react"
import { useRouter } from "next/navigation"
import { useState } from "react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Alert, AlertDescription } from "@/components/ui/alert"

interface PageLayoutProps {
  children: ReactNode
  title: string
  showBackButton?: boolean
  backHref?: string
  headerActions?: ReactNode
}

export function PageLayout({ children, title, headerActions }: PageLayoutProps) {
  const router = useRouter()
  const [isAdminDialogOpen, setIsAdminDialogOpen] = useState(false)
  const [newAdminUsername, setNewAdminUsername] = useState("")
  const [adminError, setAdminError] = useState("")
  const [isAdminSuccess, setIsAdminSuccess] = useState(false)

  const handleLogout = () => {
    // 清除认证信息
    document.cookie = "authToken=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT"
    // 跳转到登录页面
    router.push("/login")
  }

  const handleAddAdmin = () => {
    // 模拟添加管理员的逻辑
    if (!newAdminUsername.trim()) {
      setAdminError("请输入用户名")
      return
    }
    
    // 在实际应用中，这里应该调用后端API来添加管理员
    // 模拟API调用
    setTimeout(() => {
      setIsAdminSuccess(true)
      setAdminError("")
      setNewAdminUsername("")
      
      // 3秒后关闭对话框
      setTimeout(() => {
        setIsAdminDialogOpen(false)
        setIsAdminSuccess(false)
      }, 3000)
    }, 500)
  }

  const handleUsernameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setNewAdminUsername(e.target.value)
    // 当用户开始输入时，清除错误信息
    if (adminError) {
      setAdminError("")
    }
  }

  const handleDialogClose = () => {
    setIsAdminDialogOpen(false)
    // 关闭对话框时重置状态
    setAdminError("")
    setNewAdminUsername("")
    setIsAdminSuccess(false)
  }

  const handleDialogContentClick = (e: React.MouseEvent<HTMLDivElement>) => {
    // 检查点击的目标是否是输入框本身
    const target = e.target as HTMLElement;
    if (target.tagName !== 'INPUT') {
      // 如果点击的不是输入框，清除错误信息
      if (adminError) {
        setAdminError("");
      }
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Sidebar Navigation */}
      <SidebarNav />

      {/* Main Content - with left margin for sidebar */}
      <div className="ml-56 transition-all duration-300">
        {/* Header */}
        <header className="bg-white border-b border-gray-200 sticky top-0 z-10">
          <div className="max-w-5xl mx-auto px-6 py-4 flex items-center justify-between">
            <h1 className="text-xl font-semibold text-gray-900">{title}</h1>
            <div className="flex items-center gap-4">
              {headerActions}
              {/* User Info and Logout */}
              <div className="flex items-center gap-2">
                <Dialog open={isAdminDialogOpen} onOpenChange={(open) => {
                  setIsAdminDialogOpen(open)
                  // 当对话框关闭时（点击旁边或其他方式），清除错误信息
                  if (!open) {
                    setAdminError("")
                    setNewAdminUsername("")
                    setIsAdminSuccess(false)
                  }
                }}>
                  <DialogTrigger asChild>
                    <div className="flex items-center gap-2 bg-gray-100 rounded-full px-3 py-1 cursor-pointer hover:bg-gray-200 transition-colors">
                      <User className="h-4 w-4 text-gray-500" />
                      <span className="text-sm text-gray-700">管理员</span>
                    </div>
                  </DialogTrigger>
                  <DialogContent className="sm:max-w-[425px]" onClick={handleDialogContentClick}>
                    <DialogHeader>
                      <DialogTitle className="flex items-center gap-2">
                        <Shield className="h-5 w-5 text-primary-blue" />
                        新增管理员
                      </DialogTitle>
                      <DialogDescription>
                        输入要设置为管理员的用户名
                      </DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                      {isAdminSuccess ? (
                        <Alert className="border-green-500 bg-green-50">
                          <AlertDescription className="text-green-700">
                            管理员添加成功！
                          </AlertDescription>
                        </Alert>
                      ) : (
                        <>
                          <div className="grid grid-cols-4 items-center gap-4">
                            <Label htmlFor="username" className="text-right">
                              用户名
                            </Label>
                            <div className="col-span-3">
                              <Input
                                id="username"
                                value={newAdminUsername}
                                onChange={handleUsernameChange}
                                placeholder="请输入用户名"
                                className="col-span-3"
                                // 阻止在输入框内点击时冒泡到父级div
                                onClick={(e) => e.stopPropagation()}
                              />
                            </div>
                          </div>
                          {adminError && (
                            <Alert variant="destructive">
                              <AlertDescription>{adminError}</AlertDescription>
                            </Alert>
                          )}
                        </>
                      )}
                    </div>
                    {!isAdminSuccess && (
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="outline"
                          onClick={handleDialogClose}
                        >
                          取消
                        </Button>
                        <Button onClick={handleAddAdmin}>添加</Button>
                      </div>
                    )}
                  </DialogContent>
                </Dialog>
                <Button 
                  variant="ghost" 
                  size="icon"
                  onClick={handleLogout}
                  className="text-gray-500 hover:text-gray-700"
                >
                  <LogOut className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>
        </header>

        {/* Page Content */}
        <main>{children}</main>
      </div>
    </div>
  )
}